mod common;

use common::Harness;
use serde_json::{Value, json};

fn tags(h: &mut Harness, q: &str) -> Value {
    h.ok(json!({"Command": "ListQueueTags", "QueueName": q}))["Tags"].clone()
}

fn setup() -> Harness {
    let mut h = Harness::new();
    h.ok(json!({"Command": "CreateQueue", "QueueName": "q"}));
    h
}

#[test]
fn new_queue_has_no_tags_and_response_has_only_tags() {
    let mut h = setup();
    let r = h.ok(json!({"Command": "ListQueueTags", "QueueName": "q"}));
    assert_eq!(r, json!({"ok": true, "Tags": {}}));
}

#[test]
fn tag_sets_and_replaces() {
    let mut h = setup();
    let r = h.ok(json!({"Command": "TagQueue", "QueueName": "q", "Tags": {"a": "1", "B": ""}}));
    assert_eq!(r, json!({"ok": true}));
    h.ok(json!({"Command": "TagQueue", "QueueName": "q", "Tags": {"a": "2", "b": "x"}}));
    assert_eq!(tags(&mut h, "q"), json!({"a": "2", "B": "", "b": "x"}));
    h.ok(json!({"Command": "TagQueue", "QueueName": "q", "Tags": {}}));
}

#[test]
fn untag_removes_and_ignores_unknown_keys() {
    let mut h = setup();
    h.ok(json!({"Command": "TagQueue", "QueueName": "q", "Tags": {"a": "1", "b": "2"}}));
    let r = h.ok(json!({"Command": "UntagQueue", "QueueName": "q", "TagKeys": ["a", "zzz"]}));
    assert_eq!(r, json!({"ok": true}));
    assert_eq!(tags(&mut h, "q"), json!({"b": "2"}));
    h.ok(json!({"Command": "UntagQueue", "QueueName": "q", "TagKeys": []}));
}

#[test]
fn value_and_key_limits() {
    let mut h = setup();
    let t = |tags: Value| json!({"Command": "TagQueue", "QueueName": "q", "Tags": tags});
    h.ok(t(json!({"k".repeat(128): "v".repeat(256)})));
    h.ok(t(json!({"u": "é".repeat(128)})));
    for bad in [
        json!({"k".repeat(129): "v"}),
        json!({"": "v"}),
        json!({"a b": "v"}),
        json!({"a.b": "v"}),
        json!({"a": "v".repeat(257)}),
        json!({"a": "é".repeat(129)}),
        json!({"a": 1}),
        json!({"a": null}),
        json!({"a": ["x"]}),
    ] {
        assert_eq!(h.err(t(bad.clone())), "InvalidParameterValue", "{bad}");
    }
    assert_eq!(h.err(t(json!("x"))), "InvalidParameterValue");
    assert_eq!(tags(&mut h, "q").as_object().unwrap().len(), 2);
}

#[test]
fn untag_key_validation() {
    let mut h = setup();
    for bad in [json!([1]), json!([null]), json!(["a", "b c"]), json!([""]), json!("a"), json!({})] {
        let r = h.err(json!({"Command": "UntagQueue", "QueueName": "q", "TagKeys": bad.clone()}));
        assert_eq!(r, "InvalidParameterValue", "{bad}");
    }
}

#[test]
fn limit_of_50_counts_new_keys_only_and_changes_nothing_on_failure() {
    let mut h = setup();
    let many = |range: std::ops::Range<u32>| -> Value {
        Value::Object(range.map(|i| (format!("k{i}"), json!("v"))).collect())
    };
    h.ok(json!({"Command": "TagQueue", "QueueName": "q", "Tags": many(0..50)}));
    // Replacing existing keys is fine at the limit.
    h.ok(json!({"Command": "TagQueue", "QueueName": "q", "Tags": {"k0": "new"}}));
    let r = h.err(json!({"Command": "TagQueue", "QueueName": "q", "Tags": {"k0": "x", "extra": "y"}}));
    assert_eq!(r, "LimitExceeded");
    let t = tags(&mut h, "q");
    assert_eq!(t.as_object().unwrap().len(), 50);
    assert_eq!(t["k0"], "new");
    // Removing one makes room for exactly one.
    h.ok(json!({"Command": "UntagQueue", "QueueName": "q", "TagKeys": ["k1"]}));
    h.ok(json!({"Command": "TagQueue", "QueueName": "q", "Tags": {"extra": "y"}}));
    assert_eq!(h.err(json!({"Command": "TagQueue", "QueueName": "q", "Tags": {"more": "y"}})), "LimitExceeded");
}

#[test]
fn error_check_order() {
    let mut h = setup();
    assert_eq!(h.err(json!({"Command": "TagQueue", "QueueName": "q"})), "MissingParameter");
    assert_eq!(h.err(json!({"Command": "TagQueue", "Tags": {}})), "MissingParameter");
    assert_eq!(h.err(json!({"Command": "UntagQueue", "QueueName": "q"})), "MissingParameter");
    assert_eq!(h.err(json!({"Command": "ListQueueTags"})), "MissingParameter");
    // Step 3 beats the queue lookup; the lookup comes next.
    assert_eq!(
        h.err(json!({"Command": "TagQueue", "QueueName": "nope", "Tags": {"a b": "x"}})),
        "InvalidParameterValue"
    );
    for c in [
        json!({"Command": "TagQueue", "QueueName": "nope", "Tags": {}}),
        json!({"Command": "UntagQueue", "QueueName": "nope", "TagKeys": []}),
        json!({"Command": "ListQueueTags", "QueueName": "nope"}),
    ] {
        assert_eq!(h.err(c), "QueueDoesNotExist");
    }
}

#[test]
fn tags_are_not_attributes_and_survive_purge_but_not_delete() {
    let mut h = setup();
    h.ok(json!({"Command": "TagQueue", "QueueName": "q", "Tags": {"a": "1"}}));
    let before = h.ok(json!({"Command": "GetQueueAttributes", "QueueName": "q"}));
    assert!(before["Attributes"].get("a").is_none() && before["Attributes"].get("Tags").is_none());
    // CreateQueue rule 4 ignores tags: same attributes still succeeds.
    h.ok(json!({"Command": "CreateQueue", "QueueName": "q"}));
    h.ok(json!({"Command": "SendMessage", "QueueName": "q", "Body": "x"}));
    h.ok(json!({"Command": "PurgeQueue", "QueueName": "q"}));
    assert_eq!(tags(&mut h, "q"), json!({"a": "1"}));
    h.ok(json!({"Command": "DeleteQueue", "QueueName": "q"}));
    h.ok(json!({"Command": "CreateQueue", "QueueName": "q"}));
    assert_eq!(tags(&mut h, "q"), json!({}));
}
