#[test]
fn new_queue_has_no_tags_and_response_has_only_tags() {
    let mut h = setup();
    let r = h.ok(json!({"Command": "ListQueueTags", "QueueName": "q"}));
    assert_eq!(r, json!({"ok": true, "Tags": {}}));
}

#[test]
fn tag_sets_and_replaces() {
    let mut h = setup();
    let r = h.ok(json!({"Command": "TagQueue", "QueueName": "q", "Tags": {"a": "1", "B": ""}}));
    assert_eq!(r, json!({"ok": true}));
    h.ok(json!({"Command": "TagQueue", "QueueName": "q", "Tags": {"a": "2", "b": "x"}}));
    assert_eq!(tags(&mut h, "q"), json!({"a": "2", "B": "", "b": "x"}));
