//! SendMessageBatch and DeleteMessageBatch (SPEC-feature section 2).

use serde_json::{Value, json};

use super::{Broker, Members, members};
use crate::error::{Error, ErrorCode, Result};
use crate::naming;
use crate::request::Params;

const MAX_ENTRIES: usize = 10;
const MAX_ID_CHARS: usize = 80;

fn batch_error(code: ErrorCode, message: &str) -> Error {
    Error::new(code, message)
}

/// Checks batch rules 1 to 4 and returns each entry with its `Id`.
fn parse_entries(entries: &[Value]) -> Result<Vec<(&str, Params<'_>)>> {
    if entries.is_empty() {
        return Err(batch_error(
            ErrorCode::EmptyBatchRequest,
            "`Entries` has no entry",
        ));
    }
    if entries.len() > MAX_ENTRIES {
        return Err(batch_error(
            ErrorCode::TooManyEntriesInBatchRequest,
            "`Entries` has more than 10 entries",
        ));
    }
    let mut parsed: Vec<(&str, Params<'_>)> = Vec::with_capacity(entries.len());
    for entry in entries {
        let invalid = || {
            batch_error(
                ErrorCode::InvalidBatchEntryId,
                "an entry is not an object or has no valid `Id`",
            )
        };
        let object = entry.as_object().ok_or_else(invalid)?;
        let entry = Params::new(object);
        let id = entry
            .string("Id")
            .ok()
            .flatten()
            .filter(|id| naming::is_identifier(id, MAX_ID_CHARS))
            .ok_or_else(invalid)?;
        parsed.push((id, entry));
    }
    for (i, (id, _)) in parsed.iter().enumerate() {
        if parsed[..i].iter().any(|(earlier, _)| earlier == id) {
            return Err(batch_error(
                ErrorCode::BatchEntryIdsNotDistinct,
                &format!("`Id` `{id}` is used twice"),
            ));
        }
    }
    Ok(parsed)
}

impl Broker {
    pub(super) fn send_message_batch(&mut self, params: Params<'_>) -> Result<Members> {
        self.batch(params, |broker, queue, entry| {
            entry.require(&["Body"])?;
            broker.send_to(queue, entry)
        })
    }

    pub(super) fn delete_message_batch(&mut self, params: Params<'_>) -> Result<Members> {
        self.batch(params, |broker, queue, entry| {
            entry.require(&["ReceiptHandle"])?;
            broker.delete_from(queue, entry)
        })
    }

    /// Runs `handle` on each entry in order; a failed entry is reported and
    /// the rest carry on.
    fn batch(
        &mut self,
        params: Params<'_>,
        handle: fn(&mut Self, &str, Params<'_>) -> Result<Members>,
    ) -> Result<Members> {
        params.require(&["QueueName", "Entries"])?;
        let name = params.string("QueueName")?.expect("required");
        let entries = params.array("Entries")?.expect("required");
        self.queue_mut(name)?;
        let entries = parse_entries(entries)?;

        let mut successful = Vec::new();
        let mut failed = Vec::new();
        for (id, entry) in entries {
            match handle(self, name, entry) {
                Ok(mut result) => {
                    result.insert("Id".into(), json!(id));
                    successful.push(Value::Object(result));
                }
                Err(Error { code, message }) => failed.push(json!({
                    "Id": id,
                    "error": { "code": code.as_str(), "message": message },
                })),
            }
        }
        Ok(members([
            ("Successful", Value::Array(successful)),
            ("Failed", Value::Array(failed)),
        ]))
    }
}
